#[test]
fn handle_proof_raw_hash_vectors() {
    // `handle_proof(blake3(input))` should match `handle_to_proof(input)` for any UTF-8 input — this test cross-checks the two paths produce identical bytes, locking the relationship between the convenience helper and the raw primitive.
    let inputs: &[&[u8]] = &[b"", b"alice", b"\x00".as_ref(), b"\xff".as_ref()];
    let expected: &[[u8; 32]] = &[
        [0xd5, 0x24, 0x7b, 0xb2, 0x94, 0xd0, 0xae, 0x1f, 0x91, 0xb4, 0x2b, 0x69, 0x01, 0xd6, 0xab, 0x2a, 0xfe, 0xdb, 0x5f, 0x11, 0x41, 0x36, 0x96, 0x0d, 0x19, 0x49, 0xd5, 0x2c, 0xb2, 0x34, 0x7d, 0xc3],
        [0xdf, 0x72, 0x16, 0x0a, 0x62, 0x3e, 0x14, 0xaf, 0x1a, 0x16, 0x74, 0x9b, 0x7c, 0xef, 0x79, 0xe4, 0x19, 0x50, 0x5c, 0x19, 0x65, 0xaa, 0xdb, 0xfd, 0x71, 0x17, 0x34, 0x52, 0xa6, 0x17, 0xf5, 0x85],
        [0x3d, 0xa7, 0xbf, 0x90, 0x11, 0x44, 0x4a, 0x4e, 0x47, 0x74, 0xb7, 0x18, 0x4e, 0x25, 0x6a, 0x97, 0xfd, 0xda, 0x5d, 0x84, 0xb3, 0xe9, 0x62, 0xe1, 0xed, 0x95, 0x81, 0x38, 0x55, 0x75, 0xee, 0xc8],
        [0x58, 0x7a, 0x07, 0x5c, 0xa5, 0xbb, 0x53, 0x76, 0xc9, 0xb6, 0x53, 0xfe, 0x3e, 0x19, 0x9c, 0xd1, 0xff, 0x12, 0x74, 0x2f, 0x71, 0xc1, 0x03, 0x24, 0x74, 0x90, 0x20, 0x6e, 0xa4, 0x84, 0xa9, 0x06],
    ];
    for (input, expected) in inputs.iter().zip(expected.iter()) {
        let hash = blake3::hash(input);
        let actual = handle_proof(&hash);
        assert_eq!(actual.as_bytes(), expected, "handle_proof(blake3({input:?}))");
    }
}

#[test]
fn proof_to_filename_vectors() {
    // 32-byte proof → 43-char base64url + ".vsf". All-zero and all-one inputs lock the base64url alphabet (no padding, no `=`, uses `-` and `_` for the 62/63 positions).
    let vectors: &[([u8; 32], &str)] = &[
        ([0u8; 32], "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA.vsf"),
        ([0xFF; 32], "__________________________________________8.vsf"),
        ([0x71, 0xb2, 0x78, 0xf3, 0xdc, 0x43, 0x44, 0x47, 0xfc, 0x62, 0x05, 0x00, 0xe4, 0x7b, 0x6a, 0x80, 0xb0, 0xcb, 0x0d, 0xf7, 0x6a, 0x10, 0x51, 0x11, 0x9f, 0xe1, 0x9e, 0xd4, 0x95, 0x32, 0x42, 0xdf],
         "cbJ489xDREf8YgUA5HtqgLDLDfdqEFERn-Ge1JUyQt8.vsf"),
    ];
    for (proof_bytes, expected_filename) in vectors {
        let proof = blake3::Hash::from(*proof_bytes);
        let actual = proof_to_filename(&proof);
        assert_eq!(&actual, expected_filename, "proof_to_filename({proof_bytes:02x?})");
    }
}

