#[test]
fn chaos_amp_vectors() {
    // Bit-exact silicon co-verification contract. PIPE's Verilog at /mnt/Octopus/Code/pipe/rtl/chaos_amp_v2.v must produce these exact 48 output bytes for these exact 64 input bytes. Software-silicon byte divergence here is a unification break.
    //
    // Inputs:
    //   0: [0u8; 64]                                — catches missing input absorption
    //   1: [0xFFu8; 64]                             — catches missing input absorption inverse / sign-extension bugs
    //   2: blake3("alice") repeated to 64 bytes     — typical avalanche case, structured (two halves identical)
    //   3: blake3("photon") repeated to 64 bytes    — second avalanche case, distinct from (2) to catch input-dependent regressions
    let mut alice_block = [0u8; 64];
    let alice_h = blake3::hash(b"alice");
    alice_block[..32].copy_from_slice(alice_h.as_bytes());
    alice_block[32..].copy_from_slice(alice_h.as_bytes());

    let mut photon_block = [0u8; 64];
    let photon_h = blake3::hash(b"photon");
    photon_block[..32].copy_from_slice(photon_h.as_bytes());
    photon_block[32..].copy_from_slice(photon_h.as_bytes());

    let vectors: &[(&str, [u8; 64], [u8; 48])] = &[
        ("[0u8; 64]", [0u8; 64], [0x55, 0xb7, 0x2a, 0x28, 0x04, 0x56, 0x11, 0x55, 0x38, 0x9b, 0x20, 0x87, 0x0c, 0xc7, 0x12, 0xa4, 0x88, 0xb8, 0x91, 0xfd, 0xc8, 0xee, 0xd1, 0x02, 0x5b, 0x23, 0x28, 0xdc, 0x88, 0x3c, 0x74, 0x8e, 0x2f, 0x17, 0x24, 0xca, 0xc6, 0xa0, 0x6f, 0x82, 0x5a, 0x99, 0xdd, 0x1e, 0x5a, 0xbc, 0x4a, 0x54]),
        ("[0xFFu8; 64]", [0xFFu8; 64], [0x04, 0x94, 0x59, 0x06, 0xab, 0x66, 0xf1, 0x3d, 0x66, 0x99, 0xde, 0xe9, 0xef, 0xce, 0xf8, 0xf2, 0x58, 0x3c, 0x3b, 0x51, 0x6c, 0xa8, 0xee, 0x91, 0xd0, 0x32, 0xcb, 0x4b, 0x4c, 0x32, 0xcb, 0xf8, 0x40, 0x23, 0x0a, 0x0e, 0x40, 0x2c, 0x17, 0x5e, 0x41, 0xbc, 0xc2, 0x4f, 0xf7, 0xf7, 0x83, 0x5e]),
        ("blake3(\"alice\") x2", alice_block, [0x16, 0x3f, 0xaa, 0x54, 0x78, 0xca, 0x1f, 0xd2, 0x1f, 0x5b, 0x71, 0xc2, 0xc9, 0xaf, 0xd1, 0xc3, 0x21, 0x87, 0xf8, 0x30, 0x29, 0x7b, 0x02, 0xaa, 0x6d, 0x3d, 0xff, 0x3e, 0x2e, 0x4e, 0x56, 0x61, 0xa1, 0x48, 0x6f, 0xf5, 0x70, 0xc1, 0x08, 0xb1, 0x8b, 0xa9, 0x83, 0x0b, 0x38, 0xc6, 0xdd, 0xe0]),
        ("blake3(\"photon\") x2", photon_block, [0xa7, 0x4d, 0x5d, 0x0d, 0x26, 0xea, 0x89, 0xab, 0xae, 0xb9, 0x98, 0xf6, 0x08, 0x6f, 0x4a, 0x6a, 0x71, 0x81, 0x7e, 0x96, 0x4e, 0xea, 0x44, 0x4a, 0x13, 0xfa, 0xf0, 0x38, 0x11, 0x96, 0x11, 0x65, 0x7f, 0x86, 0xb0, 0xec, 0x7d, 0xa7, 0x91, 0xc6, 0x98, 0x4a, 0x8e, 0xca, 0xcb, 0x69, 0xa6, 0xbb]),
    ];
    for (label, input, expected) in vectors {
        let actual = chaos_amp(input);
        assert_eq!(&actual, expected, "chaos_amp({label})");
    }
}

#[test]
fn chaos_amp_round_consts_match_blake3() {
    // chaos_amp ROUND_CONSTS are hardcoded for no_std compatibility (BLAKE3 can't run at const-time). This test re-derives them at runtime from `blake3("PIPE chaos amp v2 - Dragonfly")` and `blake3("PIPE chaos amp v2 - Dragonfly - more")` and confirms they match the hardcoded values bit-for-bit. The seed strings are part of the cryptographic contract — renaming them silently changes every output byte and breaks software-silicon unification.
    let h1 = blake3::hash(b"PIPE chaos amp v2 - Dragonfly");
    let h2 = blake3::hash(b"PIPE chaos amp v2 - Dragonfly - more");
    let b1 = h1.as_bytes();
    let b2 = h2.as_bytes();
    let mut expected = [0u32; 16];
    for i in 0..8 {
        expected[i] = u32::from_le_bytes([b1[i * 4], b1[i * 4 + 1], b1[i * 4 + 2], b1[i * 4 + 3]]);
        expected[i + 8] =
            u32::from_le_bytes([b2[i * 4], b2[i * 4 + 1], b2[i * 4 + 2], b2[i * 4 + 3]]);
    }
    let actual = ihi::_round_consts_for_test();
    assert_eq!(
        actual, expected,
        "chaos_amp ROUND_CONSTS drifted from their BLAKE3(seed-string) derivation"
    );
}

#[test]
fn chaos_amp_deterministic_across_calls() {
    // Defensive: confirm chaos_amp produces identical bytes on repeated calls — no thread-local state, no internal randomness, no caching artifacts. If this fails, determinism is fundamentally broken.
    let block = [0x42u8; 64];
    let a = chaos_amp(&block);
    let b = chaos_amp(&block);
    assert_eq!(a, b, "chaos_amp must be a pure function of its 64-byte input");
}

#[test]
fn handle_to_proof_is_deterministic_across_calls() {
    // Defensive: confirm calling the same function twice in the same process produces identical bytes (no internal randomness, no thread-local state). If this ever fails, something's caching state between calls — fundamentally breaks the determinism contract.
    let a = handle_to_proof("photon");
    let b = handle_to_proof("photon");
    assert_eq!(a.as_bytes(), b.as_bytes(), "identical input must produce identical output every time");
}

#[test]
fn handle_to_proof_differs_for_byte_neighbors() {
    // Defensive collision-resistance smoke test: tiny input changes must produce dramatically different outputs. Hamming distance between two PoW outputs for one-byte-different inputs should be around 128 (half the bits flipped). Anything below ~80 suggests the avalanche property is degraded.
    let a = handle_to_proof("alice");
    let b = handle_to_proof("alicE");
    let hamming: u32 = a
        .as_bytes()
        .iter()
        .zip(b.as_bytes().iter())
        .map(|(x, y)| (x ^ y).count_ones())
        .sum();
    assert!(
        hamming > 80,
        "weak avalanche: only {hamming} bits differ between 'alice' and 'alicE'"
    );
}
